Here is the root cause:
The bug is caused by an unconditional `list_add` in the error path of `rxrpc_recvmsg()`. When the call fails with `-EAGAIN` due to `MSG_DONTWAIT` and the call's mutex being locked, the code always attempts to requeue the call onto the recvmsg queue without checking if it is already present. This can happen when `MSG_PEEK` is used (which does not dequeue the call) or when the I/O thread has already requeued it. The double insertion corrupts the linked list, leading to use-after-free or refcount underflows.

Here is the patch:
  */
 int rxrpc_recvmsg(struct socket *sock, struct msghdr *msg, size_t len,
 		  int flags)
 {
 	struct rxrpc_call *call;
 	struct rxrpc_sock *rx = rxrpc_sk(sock->sk);
 	struct list_head *l;
 	unsigned int call_debug_id = 0;
 	size_t copied = 0;
 	long timeo;
 	int ret;

 	DEFINE_WAIT(wait);

 	trace_rxrpc_recvmsg(0, rxrpc_recvmsg_enter, 0);

 	if (flags & (MSG_OOB | MSG_TRUNC))
 		return -EOPNOTSUPP;

 	timeo = sock_rcvtimeo(&rx->sk, flags & MSG_DONTWAIT);

 try_again:
 	lock_sock(&rx->sk);

 	/* Return immediately if a client socket has no outstanding calls */
 	if (RB_EMPTY_ROOT(&rx->calls) &&
 	    list_empty(&rx->recvmsg_q) &&
 	    skb_queue_empty_lockless(&rx->recvmsg_oobq) &&
 	    rx->sk.sk_state != RXRPC_SERVER_LISTENING) {
 		release_sock(&rx->sk);
 		return -EAGAIN;
 	}

 	if (list_empty(&rx->recvmsg_q)) {
 		ret = -EWOULDBLOCK;
 		if (timeo == 0) {
 			call = NULL;
 			goto error_no_call;
 		}

 		release_sock(&rx->sk);

 		/* Wait for something to happen */
 		prepare_to_wait_exclusive(sk_sleep(&rx->sk), &wait,
 					  TASK_INTERRUPTIBLE);
 		ret = sock_error(&rx->sk);
 		if (ret)
 			goto wait_error;

 		if (list_empty(&rx->recvmsg_q) &&
 		    skb_queue_empty_lockless(&rx->recvmsg_oobq)) {
 			if (signal_pending(current))
 				goto wait_interrupted;
 			trace_rxrpc_recvmsg(0, rxrpc_recvmsg_wait, 0);
 			timeo = schedule_timeout(timeo);
 		}
 		finish_wait(sk_sleep(&rx->sk), &wait);
 		goto try_again;
 	}

 	/* Deal with OOB messages before we consider getting normal data. */
 	if (!skb_queue_empty_lockless(&rx->recvmsg_oobq)) {
 		ret = rxrpc_recvmsg_oob(sock, msg, flags);
 		release_sock(&rx->sk);
 		if (ret == -EAGAIN)
 			goto try_again;
 		goto error_no_call;
 	}

 	/* Find the next call and dequeue it if we're not just peeking.  If we
 	 * do dequeue it, that comes with a ref that we will need to release.
 	 * We also want to weed out calls that got requeued whilst we were
 	 * shovelling data out.
 	 */
 	spin_lock_irq(&rx->recvmsg_lock);
 	l = rx->recvmsg_q.next;
 	call = list_entry(l, struct rxrpc_call, recvmsg_link);

 	if (!rxrpc_call_is_complete(call) &&
 	    skb_queue_empty(&call->recvmsg_queue) &&
 	    skb_queue_empty(&rx->recvmsg_oobq)) {
 		list_del_init(&call->recvmsg_link);
 		spin_unlock_irq(&rx->recvmsg_lock);
 		release_sock(&rx->sk);
 		trace_rxrpc_recvmsg(call->debug_id, rxrpc_recvmsg_unqueue, 0);
 		rxrpc_put_call(call, rxrpc_call_put_recvmsg);
 		goto try_again;
 	}

 	rxrpc_see_call(call, rxrpc_call_see_recvmsg);
 	if (test_bit(RXRPC_CALL_RELEASED, &call->flags)) {
 		rxrpc_see_call(call, rxrpc_call_see_already_released);
 		list_del_init(&call->recvmsg_link);
 		spin_unlock_irq(&rx->recvmsg_lock);
 		release_sock(&rx->sk);
 		trace_rxrpc_recvmsg(call->debug_id, rxrpc_recvmsg_unqueue, 0);
 		rxrpc_put_call(call, rxrpc_call_put_recvmsg);
 		goto try_again;
 	}
 	if (!(flags & MSG_PEEK))
 		list_del_init(&call->recvmsg_link);
 	else
 		rxrpc_get_call(call, rxrpc_call_get_recvmsg);
 	spin_unlock_irq(&rx->recvmsg_lock);

 	call_debug_id = call->debug_id;
 	trace_rxrpc_recvmsg(call_debug_id, rxrpc_recvmsg_dequeue, 0);

 	/* We're going to drop the socket lock, so we need to lock the call
 	 * against interference by sendmsg.
 	 */
 	if (!mutex_trylock(&call->user_mutex)) {
 		ret = -EWOULDBLOCK;
 		if (flags & MSG_DONTWAIT)
 			goto error_requeue_call;
 		ret = -ERESTARTSYS;
 		if (mutex_lock_interruptible(&call->user_mutex) < 0)
 			goto error_requeue_call;
 	}

 	release_sock(&rx->sk);

 	if (test_bit(RXRPC_CALL_RELEASED, &call->flags)) {
 		rxrpc_see_call(call, rxrpc_call_see_already_released);
 		mutex_unlock(&call->user_mutex);
 		if (!(flags & MSG_PEEK))
 			rxrpc_put_call(call, rxrpc_call_put_recvmsg);
 		goto try_again;
 	}

 	ret = rxrpc_recvmsg_user_id(call, msg, flags);
 	if (ret < 0)
 		goto error_unlock_call;

 	if (msg->msg_name && call->peer) {
 		size_t len = sizeof(call->dest_srx);

 		memcpy(msg->msg_name, &call->dest_srx, len);
 		msg->msg_namelen = len;
 	}

 	ret = rxrpc_recvmsg_data(sock, call, msg, &msg->msg_iter, len,
 				 flags, &copied);
 	if (ret == -EAGAIN)
 		ret = 0;
 	if (ret == -EIO)
 		goto call_failed;
 	if (ret < 0)
 		goto error_unlock_call;

